import {createShell,ObserverPlayer} from './shared/observer.js';import {duration,steps,stateAt,config} from './model.js';import {draw} from './scene.js';import {layout} from './layout.js';
const shell=createShell({title:config.title,sceneLabel:config.sceneLabel});const select=shell.get('step-select');select.innerHTML=steps.map((s,i)=>`<option value="${i}">${i+1} ${s.title}</option>`).join('');const note=()=>{const s=steps[Number(select.value)];shell.get('step-what').textContent=s.what;shell.get('step-detail').textContent=s.detail;};note();select.addEventListener('change',note);let size=layout(shell.host.clientWidth,shell.host.clientHeight),player;
player=new ObserverPlayer({shell,durationMs:duration*1000,overviewMs:config.overview*1000,restartFromOverview:true,render:f=>{const s=stateAt(f.local/1000,f.cycleId);shell.svg.setAttribute('viewBox',`0 0 ${size.width} ${size.height}`);shell.svg.innerHTML=draw(s,size);shell.svg.dataset.phase=String(s.index);shell.svg.dataset.cycle=String(f.cycleId);return{title:s.step.title,index:s.index,count:steps.length};},onInfo:()=>{select.value=String(stateAt(player.lastFrame.local/1000).index);note();player.openPanel();}});new ResizeObserver(()=>{size=layout(shell.host.clientWidth,shell.host.clientHeight);player.redraw();}).observe(shell.host);shell.get('seek-step').addEventListener('click',()=>{player.seek(steps[Number(select.value)].key*1000);player.closePanel();});